use anyhow::{Context, Result, bail};
use serde_json::Value;
use std::fmt::Write as FmtWrite;
use std::fs;
use std::process::Command;

use super::fonts::InstalledFonts;

const GENERATED_HEADER: &str =
    "// Generated by eigin-tools — edit design/tokens.json, not this file.\n";

/// Field order must match the `ResolvedColors` struct declaration in Theme.swift.
const COLOR_FIELDS: &[&str] = &[
    "background",
    "surface",
    "surfaceSecondary",
    "textPrimary",
    "textSecondary",
    "textTertiary",
    "accent",
    "accentSecondary",
    "border",
    "destructive",
];

/// Canonical spacing scale order.
const SPACING_FIELDS: &[&str] = &["xs", "sm", "md", "lg", "xl", "xxl"];

/// Canonical typography scale order.
const TYPOGRAPHY_FIELDS: &[&str] = &[
    "largeTitle",
    "title",
    "headline",
    "subheadline",
    "body",
    "callout",
    "label",
    "caption",
    "mono",
];

pub fn load_tokens(repo_root: &str) -> Result<Value> {
    let tokens_path = format!("{repo_root}/design/tokens.json");
    let content =
        fs::read_to_string(&tokens_path).with_context(|| format!("reading {tokens_path}"))?;
    serde_json::from_str(&content).context("parsing design/tokens.json")
}

pub fn generate(repo_root: &str, tokens: &Value, fonts: Option<&InstalledFonts>) -> Result<()> {
    let output_dir = format!("{repo_root}/src/eigin_ios/Sources/Core/Design/Generated");

    fs::create_dir_all(&output_dir).with_context(|| format!("creating {output_dir}"))?;

    emit_spacing(tokens, &output_dir)?;
    emit_typography(tokens, &output_dir, fonts)?;
    emit_font_registration(&output_dir, fonts)?;
    emit_default_theme(tokens, &output_dir)?;
    emit_color_hex(&output_dir)?;

    let status = Command::new("swiftformat")
        .arg(&output_dir)
        .status()
        .context("running swiftformat on Generated/")?;
    if !status.success() {
        anyhow::bail!("swiftformat failed on {output_dir}");
    }

    Ok(())
}

// --- Spacing ---

fn emit_spacing(tokens: &Value, output_dir: &str) -> Result<()> {
    let group = tokens
        .get("spacing")
        .context("tokens.json: missing 'spacing' group")?;

    let mut out = String::from(GENERATED_HEADER);
    out.push_str("import SwiftUI\n\n");
    out.push_str("/// App-wide spacing scale. Generated from design/tokens.json.\n");
    out.push_str("enum Spacing {\n");

    for name in SPACING_FIELDS {
        let token = group
            .get(name)
            .with_context(|| format!("tokens.json: missing spacing.{name}"))?;
        let value = token
            .get("$value")
            .and_then(Value::as_str)
            .with_context(|| format!("spacing.{name}: missing string $value"))?;
        let pts = parse_dimension(value)
            .with_context(|| format!("spacing.{name}: invalid dimension '{value}'"))?;

        if let Some(desc) = token.get("$description").and_then(Value::as_str) {
            writeln!(out, "    /// {desc}").unwrap();
        }
        writeln!(out, "    static let {name}: CGFloat = {pts}").unwrap();
    }

    out.push_str("}\n");
    write_file(output_dir, "Spacing.swift", &out)
}

fn parse_dimension(value: &str) -> Result<f64> {
    let trimmed = value.trim_end_matches("px");
    trimmed
        .parse::<f64>()
        .with_context(|| format!("not a valid px value: '{value}'"))
}

// --- Typography ---

fn emit_typography(tokens: &Value, output_dir: &str, fonts: Option<&InstalledFonts>) -> Result<()> {
    let group = tokens
        .get("typography")
        .context("tokens.json: missing 'typography' group")?;

    let mut out = String::from(GENERATED_HEADER);
    out.push_str("import SwiftUI\n\n");
    out.push_str("/// App-wide typography scale. Generated from design/tokens.json.\n");
    out.push_str("enum Typography {\n");
    out.push_str("    // Use `.typography(Typography.x)` on views, or `.font(Typography.x.font)` where a bare Font is needed.\n");

    for name in TYPOGRAPHY_FIELDS {
        let token = group
            .get(name)
            .with_context(|| format!("tokens.json: missing typography.{name}"))?;
        let value = token
            .get("$value")
            .with_context(|| format!("typography.{name}: missing $value"))?;

        let text_style = value
            .get("textStyle")
            .and_then(Value::as_str)
            .with_context(|| format!("typography.{name}: missing textStyle"))?;
        let font_weight = value
            .get("fontWeight")
            .and_then(Value::as_str)
            .with_context(|| format!("typography.{name}: missing fontWeight"))?;
        let font_design = value
            .get("fontDesign")
            .and_then(Value::as_str)
            .unwrap_or("default");
        let font_family = value.get("fontFamily").and_then(Value::as_str);
        let text_case = value.get("textCase").and_then(Value::as_str);

        let swift_style = swift_text_style(text_style)
            .with_context(|| format!("typography.{name}: unknown textStyle '{text_style}'"))?;
        let swift_weight = swift_font_weight(font_weight)
            .with_context(|| format!("typography.{name}: unknown fontWeight '{font_weight}'"))?;
        let swift_design = swift_font_design(font_design)
            .with_context(|| format!("typography.{name}: unknown fontDesign '{font_design}'"))?;

        let custom_postscript = font_family
            .zip(fonts)
            .and_then(|(family, f)| f.postscript_name(family, font_weight));

        let font_expr = if let Some(postscript) = custom_postscript {
            let base_size = text_style_default_size(text_style)
                .with_context(|| format!("typography.{name}: unknown textStyle '{text_style}'"))?;
            let scale = font_family
                .and_then(|f| fonts.map(|i| i.scale(f)))
                .unwrap_or(1.0);
            let size = (base_size as f64 * scale).round() as u32;
            format!(".custom(\"{postscript}\", size: {size})")
        } else {
            format!(".system({swift_style}, design: {swift_design}, weight: {swift_weight})")
        };

        let case_expr = match text_case {
            Some("uppercase") => ", textCase: .uppercase",
            Some("lowercase") => ", textCase: .lowercase",
            _ => "",
        };

        writeln!(
            out,
            "    static let {name} = TypographyStyle({font_expr}{case_expr})"
        )
        .unwrap();
    }

    out.push_str("}\n");
    write_file(output_dir, "Typography.swift", &out)
}

fn swift_text_style(style: &str) -> Result<&'static str> {
    Ok(match style {
        "largeTitle" => ".largeTitle",
        "title" => ".title",
        "title2" => ".title2",
        "title3" => ".title3",
        "headline" => ".headline",
        "subheadline" => ".subheadline",
        "body" => ".body",
        "callout" => ".callout",
        "footnote" => ".footnote",
        "caption" => ".caption",
        "caption2" => ".caption2",
        other => bail!("unknown textStyle: '{other}'"),
    })
}

/// Default point sizes for each UIFontTextStyle at the Large (default) Dynamic Type size.
fn text_style_default_size(style: &str) -> Result<u32> {
    Ok(match style {
        "largeTitle" => 34,
        "title" => 28,
        "title2" => 22,
        "title3" => 20,
        "headline" => 17,
        "subheadline" => 15,
        "body" => 17,
        "callout" => 16,
        "footnote" => 13,
        "caption" => 12,
        "caption2" => 11,
        other => bail!("unknown textStyle: '{other}'"),
    })
}

fn swift_font_weight(weight: &str) -> Result<&'static str> {
    Ok(match weight {
        "ultraLight" => ".ultraLight",
        "thin" => ".thin",
        "light" => ".light",
        "regular" => ".regular",
        "medium" => ".medium",
        "semibold" => ".semibold",
        "bold" => ".bold",
        "heavy" => ".heavy",
        "black" => ".black",
        other => bail!("unknown fontWeight: '{other}'"),
    })
}

fn swift_font_design(design: &str) -> Result<&'static str> {
    Ok(match design {
        "default" => ".default",
        "serif" => ".serif",
        "rounded" => ".rounded",
        "monospaced" => ".monospaced",
        other => bail!("unknown fontDesign: '{other}'"),
    })
}

// --- FontRegistration ---

fn emit_font_registration(output_dir: &str, fonts: Option<&InstalledFonts>) -> Result<()> {
    let mut out = String::from(GENERATED_HEADER);

    if let Some(installed) = fonts {
        let large_title_ps = installed
            .postscript_name("sansSerif", "bold")
            .unwrap_or("NorthEastCN-Bold");
        let inline_title_ps = installed
            .postscript_name("sansSerif", "semibold")
            .unwrap_or("NorthEastCN-SemiBold");

        out.push_str("import CoreText\nimport Foundation\nimport UIKit\n\n");
        out.push_str("enum FontRegistration {\n");

        out.push_str("    static func register() {\n");
        out.push_str("        let names: [String] = [\n");
        for name in &installed.file_names {
            writeln!(out, "            \"{name}\",").unwrap();
        }
        out.push_str("        ]\n");
        out.push_str("        for name in names {\n");
        out.push_str(
            "            guard let url = Bundle.main.url(forResource: name, withExtension: nil) else { continue }\n",
        );
        out.push_str("            CTFontManagerRegisterFontsForURL(url as CFURL, .process, nil)\n");
        out.push_str("        }\n");
        out.push_str("    }\n\n");

        out.push_str("    @MainActor static func configureNavigationBar() {\n");
        writeln!(out, "        let large = UIFont(name: \"{large_title_ps}\", size: 34) ?? .preferredFont(forTextStyle: .largeTitle)").unwrap();
        writeln!(out, "        let inline = UIFont(name: \"{inline_title_ps}\", size: 17) ?? .preferredFont(forTextStyle: .headline)").unwrap();
        out.push_str(
            "        UINavigationBar.appearance().largeTitleTextAttributes = [.font: large]\n",
        );
        out.push_str(
            "        UINavigationBar.appearance().titleTextAttributes = [.font: inline]\n",
        );
        out.push_str("    }\n");

        out.push_str("}\n");
    } else {
        out.push_str("import SwiftUI\n\n");
        out.push_str("enum FontRegistration {\n");
        out.push_str("    static func register() {}\n");
        out.push_str("    @MainActor static func configureNavigationBar() {}\n");
        out.push_str("}\n");
    }

    write_file(output_dir, "FontRegistration.swift", &out)
}

// --- DefaultTheme ---

/// Resolves a DTCG alias (`{a.b.c}`) to a plain string value, following alias chains.
/// Plain (non-reference) strings are returned as-is. Bails after 16 hops to catch cycles.
fn resolve_alias<'a>(tokens: &'a Value, raw: &'a str, depth: u8) -> Result<&'a str> {
    if depth > 16 {
        bail!("token ref cycle or excessive depth near '{raw}'");
    }
    let Some(path) = raw.strip_prefix('{').and_then(|s| s.strip_suffix('}')) else {
        return Ok(raw);
    };
    let mut node = tokens;
    for part in path.split('.') {
        node = node
            .get(part)
            .with_context(|| format!("token ref '{raw}': missing '{part}'"))?;
    }
    let value = node
        .get("$value")
        .and_then(Value::as_str)
        .with_context(|| format!("token ref '{raw}': target has no string $value"))?;
    resolve_alias(tokens, value, depth + 1)
}

fn emit_default_theme(tokens: &Value, output_dir: &str) -> Result<()> {
    let group = tokens
        .get("color")
        .context("tokens.json: missing 'color' group")?;

    let mut light_entries = Vec::new();
    let mut dark_entries = Vec::new();

    for &name in COLOR_FIELDS {
        let token = group
            .get(name)
            .with_context(|| format!("tokens.json: missing color.{name}"))?;
        let light_raw = token
            .get("$value")
            .and_then(Value::as_str)
            .with_context(|| format!("color.{name}: missing string $value"))?;
        let dark_raw = token
            .get("$modes")
            .and_then(|m| m.get("dark"))
            .and_then(Value::as_str)
            .unwrap_or(light_raw);

        let light =
            resolve_alias(tokens, light_raw, 0).with_context(|| format!("color.{name}.$value"))?;
        let dark = resolve_alias(tokens, dark_raw, 0)
            .with_context(|| format!("color.{name}.$modes.dark"))?;

        light_entries.push((name, light.to_string()));
        dark_entries.push((name, dark.to_string()));
    }

    let mut out = String::from(GENERATED_HEADER);
    out.push_str("import SwiftUI\n\n");
    out.push_str("/// Default Eigin theme. Generated from design/tokens.json.\n");
    out.push_str("struct DefaultTheme: Theme {\n");
    out.push_str("    var name: String { Localized.Ui.defaultLabel }\n");
    out.push_str("    let id = \"default\"\n\n");
    out.push_str("    func colors(for colorScheme: ColorScheme) -> ResolvedColors {\n");
    out.push_str("        switch colorScheme {\n");

    for (mode_label, entries) in [("light", &light_entries), ("dark", &dark_entries)] {
        writeln!(out, "        case .{mode_label}:").unwrap();
        out.push_str("            return ResolvedColors(\n");
        let last = entries.len().saturating_sub(1);
        for (i, (name, hex)) in entries.iter().enumerate() {
            let comma = if i < last { "," } else { "" };
            writeln!(out, "                {name}: Color(hex: \"{hex}\"){comma}").unwrap();
        }
        out.push_str("            )\n");
    }

    out.push_str("        @unknown default:\n");
    out.push_str("            return colors(for: .light)\n");
    out.push_str("        }\n");
    out.push_str("    }\n");
    out.push_str("}\n");

    write_file(output_dir, "DefaultTheme.swift", &out)
}

// --- Color+Hex ---

fn emit_color_hex(output_dir: &str) -> Result<()> {
    let out = format!(
        concat!(
            "{header}",
            "import SwiftUI\n\n",
            "extension Color {{\n",
            "    init(hex: String) {{\n",
            "        let hex = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)\n",
            "        var int: UInt64 = 0\n",
            "        Scanner(string: hex).scanHexInt64(&int)\n",
            "        let r = Double((int >> 16) & 0xFF) / 255\n",
            "        let g = Double((int >> 8) & 0xFF) / 255\n",
            "        let b = Double(int & 0xFF) / 255\n",
            "        self.init(red: r, green: g, blue: b)\n",
            "    }}\n",
            "}}\n"
        ),
        header = GENERATED_HEADER,
    );
    write_file(output_dir, "Color+Hex.swift", &out)
}

// --- Helpers ---

fn write_file(dir: &str, filename: &str, content: &str) -> Result<()> {
    let path = format!("{dir}/{filename}");
    fs::write(&path, content).with_context(|| format!("writing {path}"))
}
